#include <cstdio>
#include <vector>

double mse(const std::vector<double>& x, const std::vector<double>& y, double w, double b) {
    double suma = 0.0;
    for (std::size_t i = 0; i < x.size(); ++i) {
        const double error = w * x[i] + b - y[i];
        suma += error * error;
    }
    return suma / static_cast<double>(x.size());
}

int main() {
    const std::vector<double> x{1.0, 2.0, 3.0, 4.0};
    const std::vector<double> y{2.0, 4.0, 6.0, 8.0};

    std::printf("(0, 0)    -> %.6f\n", mse(x, y, 0.0, 0.0));
    std::printf("(1.5, 0.5) -> %.6f\n", mse(x, y, 1.5, 0.5));
    std::printf("(2, 0)    -> %.6f\n", mse(x, y, 2.0, 0.0));
    return 0;
}

#include <cmath>
#include <cstdio>
#include <vector>

int main() {
    const std::vector<double> x{1.0, 2.0, 3.0, 4.0};
    const std::vector<double> y{2.0, 4.0, 6.0, 8.0};
    const std::size_t n = x.size();

    double w = 0.0;
    double b = 0.0;
    const double lr = 0.05;

    for (int epoca = 1; epoca <= 20000; ++epoca) {
        double gw = 0.0;
        double gb = 0.0;
        for (std::size_t i = 0; i < n; ++i) {
            const double error = w * x[i] + b - y[i];
            gw += 2.0 * x[i] * error / static_cast<double>(n);
            gb += 2.0 * error / static_cast<double>(n);
        }
        w -= lr * gw;
        b -= lr * gb;

        if (std::fabs(gw) < 1e-3 && std::fabs(gb) < 1e-3) {
            std::printf("parada en la epoca %d: w=%.6f b=%.6f\n", epoca, w, b);
            return 0;
        }
    }
    std::printf("no convergio en 20000 epocas\n");
    return 0;
}

